 import (
 	"go/ast"
+	"go/doc/comment"
 )

+// DocLinkVisitor visits every doc-link reference found in doc comments.
+// Unlike DocCommentVisitor, it parses the doc comment text to extract
+// bracket-notation symbol links and visits each one individually.
+type DocLinkVisitor interface {
+	walkerEvents
+	VisitDocLink(link *comment.DocLink, decl ast.Node, cg *ast.CommentGroup)
+}
+
 // DocCommentVisitor visits every doc-comment.
 // Does not visit doc-comments for function-local definitions (types, etc).
 // Also does not visit package doc-comment (file-level doc-comments).
